import type { Metadata } from 'next'
import Link from 'next/link'
import { useRouter } from 'next/navigation'

interface Post {
  id: number
  title: string
  body: string
}

interface HomePageProps {
  searchParams: Promise<{ [key: string]: string | string[] | undefined }>
}

export async function generateMetadata(): Promise<Metadata> {
  return {
    title: 'Home - My Blog',
    description: 'Welcome to my blog homepage',
    openGraph: {
      title: 'Home - My Blog',
    },
  }
}

async function getPosts(): Promise<Post[]> {
  const res = await fetch('https://jsonplaceholder.typicode.com/posts?_limit=5', {
    cache: 'no-store',
  })
  return res.json()
}

async function getUserAgent(): Promise<string> {
  return 'Server-side rendered'
}

export default async function HomePage({ searchParams }: HomePageProps) {
  const [posts, userAgent] = await Promise.all([getPosts(), getUserAgent()])
  const params = await searchParams
  const timestamp = new Date().toISOString()

  return (
    <div>
      <h1>Welcome to My Blog</h1>
      <p>Server-side rendered at: {timestamp}</p>
      <p>Your user agent: {userAgent}</p>

      <h2>Recent Posts</h2>
      <ul>
        {posts.map((post) => (
          <li key={post.id}>
            <Link href={`/blog/${post.id}`}>{post.title}</Link>
          </li>
        ))}
      </ul>
    </div>
  )
}

import type { Metadata } from 'next'
import Link from 'next/link'

interface Post {
  id: number
  title: string
  body: string
}

export const metadata: Metadata = {
  title: 'Blog - My Blog',
  description: 'All blog posts',
}

export const revalidate = 60

async function getPosts(): Promise<Post[]> {
  const res = await fetch('https://jsonplaceholder.typicode.com/posts', {
    next: { revalidate: 60 },
  })
  return res.json()
}

export default async function BlogIndex() {
  const posts = await getPosts()

  return (
    <div>
      <h1>All Blog Posts</h1>

      <div className="posts-grid">
        {posts.map((post) => (
          <div key={post.id} className="post-card">
            <h2>
              <Link href={`/blog/${post.id}`}>{post.title}</Link>
            </h2>
            <p>{post.body.substring(0, 100)}...</p>
            <Link href={`/blog/${post.id}`}>
              <button>Read More</button>
            </Link>
          </div>
        ))}
      </div>
    </div>
  )
}

import type { Metadata } from 'next'
import Link from 'next/link'
import { notFound } from 'next/navigation'

interface Comment {
  id: number
  name: string
  body: string
  email: string
}

interface Post {
  id: number
  title: string
  body: string
}

interface BlogPostProps {
  params: Promise<{ id: string }>
}

export async function generateMetadata({ params }: BlogPostProps): Promise<Metadata> {
  const { id } = await params
  try {
    const res = await fetch(`https://jsonplaceholder.typicode.com/posts/${id}`, {
      next: { revalidate: 300 },
    })
    if (!res.ok) return { title: 'Post Not Found' }
    const post: Post = await res.json()
    return {
      title: `${post.title} - My Blog`,
      description: post.body.substring(0, 160),
      openGraph: {
        title: post.title,
        description: post.body.substring(0, 160),
      },
    }
  } catch {
    return { title: 'Post Not Found' }
  }
}

async function getPost(id: string): Promise<Post | null> {
  const res = await fetch(`https://jsonplaceholder.typicode.com/posts/${id}`, {
    next: { revalidate: 300 },
  })
  if (!res.ok) return null
  return res.json()
}

async function getComments(id: string): Promise<Comment[]> {
  const res = await fetch(
    `https://jsonplaceholder.typicode.com/posts/${id}/comments`,
    { next: { revalidate: 300 } }
  )
  return res.json()
}

export default async function BlogPost({ params }: BlogPostProps) {
  const { id } = await params
  const post = await getPost(id)

  if (!post) {
    notFound()
  }

  const comments = await getComments(id)

  return (
    <article>
      <Link href="/blog">← Back</Link>

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  )
}

