'use client'

import { useEffect } from 'react'

interface ErrorProps {
  error: Error & { digest?: string }
  reset: () => void
}

export default function Error({ error, reset }: ErrorProps) {
  useEffect(() => {
    console.error(error)
  }, [error])

  const isNotFound = error.message?.includes('NOT_FOUND') || error.digest?.includes('NOT_FOUND')

  return (
    <div className="error-page">
      <h1>
        {isNotFound
          ? 'A 404 error occurred on server'
          : 'An error occurred on client'}
      </h1>
      <p>
        {isNotFound
          ? 'This page could not be found.'
          : 'Sorry, something went wrong.'}
      </p>
      <button onClick={reset}>Try again</button>
    </div>
  )
}

import { NextRequest, NextResponse } from 'next/server'

interface Post {
  id: number
  title: string
  content: string
  createdAt?: string
}

export async function GET() {
  const posts: Post[] = [
    { id: 1, title: 'First Post', content: 'This is the first post' },
    { id: 2, title: 'Second Post', content: 'This is the second post' },
  ]

  return NextResponse.json(posts)
}

export async function POST(request: NextRequest) {
  try {
    const body = await request.json()
    const { title, content } = body

    if (!title || !content) {
      return NextResponse.json(
        { error: 'Title and content are required' },
        { status: 400 }
      )
    }

    const newPost: Post = {
      id: Date.now(),
      title,
      content,
      createdAt: new Date().toISOString(),
    }

    return NextResponse.json(newPost, { status: 201 })
  } catch {
    return NextResponse.json(
      { error: 'Invalid request body' },
      { status: 400 }
    )
  }
}

import { NextRequest, NextResponse } from 'next/server'

interface Post {
  id: number
  title: string
  content: string
  createdAt?: string
  updatedAt?: string
}

interface RouteParams {
  params: Promise<{ id: string }>
}

export async function GET(request: NextRequest, { params }: RouteParams) {
  const { id } = await params

  const post: Post = {
    id: parseInt(id),
    title: `Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  }

  return NextResponse.json(post)
}

export async function PUT(request: NextRequest, { params }: RouteParams) {
  const { id } = await params
  const body = await request.json()
  const { title, content } = body

  const updatedPost: Post = {
    id: parseInt(id),
    title: title || `Post ${id}`,
    content: content || `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  }

  return NextResponse.json(updatedPost)
}

export async function DELETE(request: NextRequest, { params }: RouteParams) {
  const { id } = await params

  return NextResponse.json({ message: `Post ${id} deleted successfully` })
}

'use client'

import { createContext, useContext, useState, ReactNode } from 'react'

interface AppContextValue {
  theme: string
  setTheme: (theme: string) => void
}

const AppContext = createContext<AppContextValue | undefined>(undefined)

interface AppProviderProps {
  children: ReactNode
}

export function AppProvider({ children }: AppProviderProps) {
  const [theme, setTheme] = useState<string>('light')

  return (
    <AppContext.Provider value={{ theme, setTheme }}>
      {children}
    </AppContext.Provider>
  )
}

export function useAppContext(): AppContextValue {
  const context = useContext(AppContext)
  if (!context) {
    throw new Error('useAppContext must be used within AppProvider')
  }
  return context
}

